package com.gazkademe.pro;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import android.graphics.Color;import androidx.webkit.WebViewAssetLoader;import android.content.Intent;
public class MainActivity extends Activity {
WebView web;
@Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(7,22,37));getWindow().setNavigationBarColor(Color.rgb(7,22,37));web=new WebView(this);web.setBackgroundColor(Color.rgb(7,22,37));setContentView(web);web.addJavascriptInterface(new Object(){@JavascriptInterface public void pulse(String kind){runOnUiThread(()->{web.performHapticFeedback(kind.equals("error")?android.view.HapticFeedbackConstants.LONG_PRESS:android.view.HapticFeedbackConstants.KEYBOARD_TAP);});}},"GazHaptics");WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);final WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return loader.shouldInterceptRequest(r.getUrl());}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if("appassets.androidplatform.net".equals(r.getUrl().getHost()))return false;if("https".equals(r.getUrl().getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception ignored){}}return true;}});web.setWebChromeClient(new WebChromeClient());if(b==null||web.restoreState(b)==null)web.loadUrl("https://appassets.androidplatform.net/assets/index.html");}
@Override protected void onSaveInstanceState(Bundle b){web.saveState(b);super.onSaveInstanceState(b);}
@Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}